#!/usr/bin/env bash
# Verify the authored firmware; no guest instructions are generated by this host harness.
set -euo pipefail
if [[ $# != 2 ]]; then
  echo "Usage: $0 /path/to/qemu-system-xtensa new-evidence-dir" >&2
  exit 2
fi
qemu=$(realpath "$1")
app=$(cd -- "$(dirname -- "$0")" && pwd)
mkdir -- "$2"
out=$(realpath "$2")
python3 - "$app/build/phy-txbbgain.bin" "$out" <<'PY'
import hashlib
from pathlib import Path
import sys

image = Path(sys.argv[1]).read_bytes()
out = Path(sys.argv[2])
assert len(image) == 240
assert hashlib.sha256(image).hexdigest() == "f4cd821a7f02e6d42214f50388889ccb1af10acc91d1260cf793ec94751050d9"

def flash_fixture(name, data):
    (out / name).write_bytes(data + b"\xff" * (0x400000 - len(data)))

flash_fixture("good.bin", image)
# Change only one known expected result in the data slot, not any machine instruction.
bad = bytearray(image)
assert bad[0xa0] == 3
bad[0xa0] = 4
bad[0xcf] ^= 3 ^ 4
bad[0xd0:0xf0] = hashlib.sha256(bad[:0xd0]).digest()
flash_fixture("bad.bin", bad)
PY
for kind in good bad; do
  status=0
  timeout 5s "$qemu" -M esp32s3 -display none -monitor none -serial "file:$out/$kind.uart" \
    -nic none -no-reboot -drive "file=$out/$kind.bin,format=raw,if=mtd" \
    -d in_asm -trace "enable=memory_region_ops_write,file=$out/$kind.trace" \
    > "$out/$kind.stderr" 2>&1 || status=$?
  [[ "$status" == 124 ]]
  grep -Fq 'entry 0x403c870c' "$out/$kind.uart"
done
[[ "$(tail -c 1 "$out/good.uart")" == P ]]
[[ "$(tail -c 1 "$out/bad.uart")" == F ]]
grep -Eq '^0x403c8721:[[:space:]]+callx0[[:space:]]+a8' "$out/good.trace"
grep -Eq 'addr 0x60000000 value 0x50 size 4 name .esp_soc.uart.' "$out/good.trace"
grep -Eq 'addr 0x60000000 value 0x46 size 4 name .esp_soc.uart.' "$out/bad.trace"
printf 'PASS: 7 vectors; data-only mutation fails self-test as expected\n'
